// ── Validates the form submission and picks a report definition ──
// To add a report: add an entry to REPORTS below, then add a matching
// option to the "Report Type" dropdown on the Form Trigger node.
//
//   sheetName  - the tab to read
//   dateColumn - column used for the date-range filter
//   groupBy    - column to group rows by
//   sumColumn  - numeric column to total per group

const form = $input.first().json;

const reportType = form['Report Type'];
const startDate  = form['Start Date'];
const endDate    = form['End Date'];
const email      = form['Email Address'];

if (!startDate || !endDate) {
  throw new Error('Both Start Date and End Date are required.');
}
if (new Date(endDate) < new Date(startDate)) {
  throw new Error('End Date must be on or after Start Date.');
}

const REPORTS = {
  'Sales Summary': {
    label: 'Sales Summary',
    sheetName: 'Orders',
    dateColumn: 'Date',
    groupBy: 'Product',
    sumColumn: 'Amount',
  },
  'New Customers': {
    label: 'New Customers',
    sheetName: 'Customers',
    dateColumn: 'Signup Date',
    groupBy: 'Source',
    sumColumn: 'Lifetime Value',
  },
  'Refunds': {
    label: 'Refunds',
    sheetName: 'Refunds',
    dateColumn: 'Refund Date',
    groupBy: 'Reason',
    sumColumn: 'Amount',
  },
};

const report = REPORTS[reportType];
if (!report) {
  throw new Error('Unknown report type: ' + reportType);
}

const slug = report.label.toLowerCase().replace(/[^a-z0-9]+/g, '-');

return [{
  json: {
    ...report,
    startDate,
    endDate,
    email,
    fileName: slug + '_' + startDate + '_to_' + endDate + '.csv',
    requestedAt: new Date().toISOString(),
  },
}];

// ── Filters the sheet by date range, then groups and totals ──
// Google Sheets has no server-side date filtering, so the whole tab is
// read and narrowed here. Fine up to a few thousand rows; past that,
// keep a pre-filtered tab or move to a database.

const cfg  = $('Validate & Pick Report').first().json;
const rows = $input.all().map(i => i.json);

// Sheets hands back dates as ISO strings, locale strings, or serial numbers.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    // Sheets serial date: days since 1899-12-30
    return new Date(Date.UTC(1899, 11, 30) + v * 86400000);
  }
  const s = String(v).trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  const us = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (us) return new Date(Number(us[3]), Number(us[1]) - 1, Number(us[2]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

// Strips currency symbols and thousands separators before summing.
function toNumber(v) {
  if (typeof v === 'number') return v;
  const n = Number(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
}

const start = parseDate(cfg.startDate);
const end   = parseDate(cfg.endDate);
end.setHours(23, 59, 59, 999);

const inRange = rows.filter(r => {
  const d = parseDate(r[cfg.dateColumn]);
  return d && d >= start && d <= end;
});

const groups = new Map();
for (const r of inRange) {
  const key = String(r[cfg.groupBy] ?? 'Unknown').trim() || 'Unknown';
  const g = groups.get(key) ?? { key, records: 0, total: 0 };
  g.records += 1;
  g.total   += toNumber(r[cfg.sumColumn]);
  groups.set(key, g);
}

const result = [...groups.values()]
  .sort((a, b) => b.total - a.total)
  .map(g => ({
    [cfg.groupBy]:   g.key,
    Records:         g.records,
    [cfg.sumColumn]: Math.round(g.total * 100) / 100,
  }));

return result.map(json => ({ json }));

// ── Builds an HTML preview table + total, and carries the CSV binary through ──

const cfg  = $('Validate & Pick Report').first().json;
const rows = $('Filter & Aggregate').all().map(i => i.json).filter(r => Object.keys(r).length);

const columns = rows.length ? Object.keys(rows[0]) : [];
const PREVIEW = 25;
const preview = rows.slice(0, PREVIEW);

const total   = rows.reduce((sum, r) => sum + (Number(r[cfg.sumColumn]) || 0), 0);
const records = rows.reduce((sum, r) => sum + (Number(r.Records) || 0), 0);

const th = 'padding:8px 12px;text-align:left;border-bottom:2px solid #ddd;font-size:13px;';
const td = 'padding:8px 12px;border-bottom:1px solid #eee;font-size:13px;';

const head = columns.map(c => '<th style="' + th + '">' + c + '</th>').join('');
const body = preview
  .map(r => '<tr>' + columns.map(c => '<td style="' + td + '">' + (r[c] ?? '') + '</td>').join('') + '</tr>')
  .join('');

const truncated = rows.length > PREVIEW
  ? '<p style="font-size:12px;color:#888;">Showing the top ' + PREVIEW + ' of ' + rows.length + ' groups. The full breakdown is attached as a CSV.</p>'
  : '';

const html = `
<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#222;max-width:720px;">
  <h2 style="margin:0 0 4px;">${cfg.label}</h2>
  <p style="margin:0 0 16px;color:#666;font-size:14px;">
    ${cfg.startDate} &rarr; ${cfg.endDate} &middot;
    ${records.toLocaleString()} rows across ${rows.length} ${cfg.groupBy} groups &middot;
    ${cfg.sumColumn} total: <strong>${total.toLocaleString()}</strong>
  </p>
  <table style="border-collapse:collapse;width:100%;"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>
  ${truncated}
  <p style="font-size:12px;color:#aaa;margin-top:24px;">Generated by n8n from the "${cfg.sheetName}" tab.</p>
</div>`.trim();

return [{
  json: {
    html,
    subject: cfg.label + ': ' + cfg.startDate + ' to ' + cfg.endDate,
    email: cfg.email,
    groupCount: rows.length,
    total,
  },
  binary: $input.first().binary,
}];
